<script setup>
import {ref} from 'vue';import {httpsCallable} from 'firebase/functions';import {functions} from '../firebase';
const text=ref(''),busy=ref(false);async function announce(){if(!text.value.trim())return;busy.value=true;try{await httpsCallable(functions,'createAnnouncement')({text:text.value.trim()});text.value='';alert('Duyuru yayınlandı.')}catch(e){alert(e.message)}finally{busy.value=false}}
</script><template><h1>🔥 DEVELOPER Yönetim Paneli</h1><div class="grid"><div class="card"><h2>📢 Duyuru yayınla</h2><textarea class="field" rows="6" v-model="text" maxlength="1000" placeholder="Tüm kullanıcılara duyuru..."></textarea><button class="btn" :disabled="busy" @click="announce">{{busy?'Yayınlanıyor...':'Duyuruyu yayınla'}}</button></div><div class="card"><h2>⚙ Sistem</h2><p class="muted">DEVELOPER rolü tüm moderasyon işlemlerini, duyuruları ve sistem yönetimini yapabilir.</p><div class="tags"><span class="tag">Role: DEVELOPER</span><span class="tag">Kullanıcı: Mavi</span></div></div></div></template>
